verification_receipts.patch_excerpt:
diff --git a/scripts/test-executor-profiles.js b/scripts/test-executor-profiles.js
index 3178834..7b7aa30 100644
--- a/scripts/test-executor-profiles.js
+++ b/scripts/test-executor-profiles.js
@@ -156,7 +156,21 @@ const wrapperInput = {
 };
 const wrapper = profiles.createForkReceiptWrapper({ ...wrapperInput, signingKey });
 const publicKey = crypto.createPublicKey(signingKey);
-assert.equal(profiles.verifyForkReceiptWrapper(wrapper, { publicKey, expected: wrapperInput }).status, 'verified');
+const verifiedVerification = profiles.verifyForkReceiptWrapper(wrapper, { publicKey, expected: wrapperInput });
+assert.equal(verifiedVerification.status, 'verified');
+
+// A cryptographically verified receipt must never launder a missing model
+// observation into a verified model match: model proof and receipt proof
+// are independent facts.
+const missingTelemetryWithVerifiedReceipt = profiles.missionControlExecutorState({
+  profile: local, observation: null, wrapper, verification: verifiedVerification,
+});
+assert.equal(missingTelemetryWithVerifiedReceipt.receipt_status, 'verified');
+assert.equal(missingTelemetryWithVerifiedReceipt.observed_model, null);
+assert.equal(missingTelemetryWithVerifiedReceipt.model_status, 'unknown');
+assert.equal(missingTelemetryWithVerifiedReceipt.model_reason_code, 'MODEL_OBSERVATION_MISSING');
+assert.notEqual(missingTelemetryWithVerifiedReceipt.model_status, 'verified');
+assert.notEqual(missingTelemetryWithVerifiedReceipt.model_status, 'passed');
 for (const field of ['fork_id', 'branch_id', 'contract_digest', 'executor_profile_digest', 'execution_receipt_digest', 'observation_digest']) {
   const tampered = copy(wrapper);
   tampered.receipt[field] = field.endsWith('digest') ? `sha256:${'c'.repeat(64)}` : `${tampered.receipt[field]}-tampered`;
